const budgets = $('Select rows from a table').all().map(i => i.json);
const spending = $('Execute a SQL query1').all().map(i => i.json);
const goalRows = $('Select rows from a table1').all().map(i => i.json);
const budgetAnalysis = budgets.map(budget => {
  const spendingRow = spending.find(
    s => s.category === budget.category
  );

  const limit = Number(budget.monthly_limit) || 0;
  const spent = Number(spendingRow?.spent) || 0;

  return {
    category: budget.category,
    budget: limit,
    spent,
    remaining: limit - spent,
    percentage_used: limit > 0
      ? Number(((spent / limit) * 100).toFixed(2))
      : 0
  };
});

const goal = goalRows[0] || null;

let goalAnalysis = null;

if (goal) {
  const target = Number(goal.target_amount);
  const current = Number(goal.current_amount);
  const remaining = target - current;

  const today = new Date();
  const targetDate = new Date(goal.target_date);

  const monthsRemaining = Math.max(
    1,
    (targetDate.getFullYear() - today.getFullYear()) * 12 +
    (targetDate.getMonth() - today.getMonth())
  );

  goalAnalysis = {
    goal_name: goal.goal_name,
    target_amount: target,
    current_amount: current,
    remaining_amount: remaining,
    target_date: goal.target_date,
    months_remaining: monthsRemaining,
    required_monthly_saving:
      Number((remaining / monthsRemaining).toFixed(2))
  };
}

return [
  {
    json: {
      budget_analysis: budgetAnalysis,
      goal_analysis: goalAnalysis
    }
  }
];

